import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;notes=[]
def gettok():
    global tok
    while True:
        try:
            tok=json.load(urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST")))["token"];return
        except urllib.error.HTTPError as e:
            time.sleep(float(e.headers.get("Retry-After") or 1))
def get(p):
    global tok
    if not tok: gettok()
    for a in range(200):
        try:
            r=urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok})
            return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            if e.code==401: gettok()
            elif e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1))
            elif e.code==404 and p.startswith("/customers"): return None
            else: notes.append((p,e.code)); time.sleep(0.5)
        except Exception as e: notes.append((p,str(e))); time.sleep(0.5)
    raise SystemExit("fail "+p)
seen={};dups=0;p=1
first=get("/orders?page=1");tp=first["total_pages"];pages=[first]
for n in range(2,tp+1): pages.append(get(f"/orders?page={n}"))
for pg in pages:
    for o in pg["items"]:
        if o["id"] in seen:
            dups+=1
            if seen[o["id"]]!=o: notes.append(("dupdiff",o,seen[o["id"]]))
        else: seen[o["id"]]=o
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={k:0 for k in["north","south","east","west"]};cnt=0;statuses=set();tzs=set()
for o in seen.values():
    statuses.add(o["status"])
    s=o["placed_at"].replace("Z","+00:00");d=datetime.fromisoformat(s)
    if d.tzinfo is None: tzs.add("naive:"+o["placed_at"]); d=d.replace(tzinfo=timezone.utc)
    d=d.astimezone(timezone.utc)
    if o["status"]!="shipped" or not(lo<=d<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    C=cust[c]
    if C is None: notes.append(("nocust",o));continue
    v=(o["amount_cents"]*(100-C["discount_pct"])*2+100)//200  # half up
    reg[C["region"]]+=v;cnt+=1
r={"total_cents":sum(reg.values()),"order_count":cnt,"duplicates_skipped":dups,"by_region":reg}
json.dump(r,open("/workspace/result.json","w"),indent=2)
print(r,tp,len(seen),statuses,list(tzs)[:5]);print(notes[:20],len(notes))
print(set(type(x["amount_cents"]) for x in seen.values()), {c:v for c,v in cust.items() if v and v["region"] not in reg})
EOF
